import "./logos.css";

export interface LogoItem {
  src: string;
  label: string;
}
export interface LogoCloudProps {
  heading: string;
  style: "mono" | "color";
  height: "small" | "medium" | "large";
  logos: LogoItem[];
}

export function LogoCloudRender({ heading, style, height, logos }: LogoCloudProps) {
  return (
    <div className="p1-logo-cloud p1-block" data-style={style} data-height={height}>
      <div className="p1-logo-cloud__inner">
        {heading && <div className="p1-logo-cloud__heading">{heading}</div>}
        <div className="p1-logo-cloud__list">
          {(logos || []).map((l, i) =>
            l.src ? (
              <img
                key={i}
                src={l.src}
                alt={l.label || ""}
                className="p1-logo-cloud__img"
              />
            ) : (
              <div key={i} className="p1-logo-cloud__placeholder">{l.label || "Logo"}</div>
            )
          )}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { LogoCloudRender, type LogoCloudProps, type LogoItem } from "./logos";
export type { LogoCloudProps, LogoItem };

export const LogoCloudBlock: ComponentConfig<LogoCloudProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label above the logos. E.g. Featured in or Trusted by." },
    },
    style: {
      type: "radio" as const,
      options: [
        { label: "Mono", value: "mono" },
        { label: "Color", value: "color" },
      ],
    },
    height: {
      type: "select" as const,
      options: [
        { label: "Small", value: "small" },
        { label: "Medium", value: "medium" },
        { label: "Large", value: "large" },
      ],
    },
    logos: {
      type: "array" as const,
      arrayFields: {
        src: {
          type: "text" as const,
          ai: { exclude: true },
        },
        label: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Brand or publication name. E.g. Reuters." },
        },
      },
      defaultItemProps: { src: "", label: "Brand" },
      getItemSummary: (item: LogoItem) => item.label || "Logo",
    },
  },
  defaultProps: {
    heading: "Featured in",
    style: "mono",
    height: "medium",
    logos: [
      { src: "", label: "NPR" },
      { src: "", label: "PBS" },
      { src: "", label: "REUTERS" },
      { src: "", label: "NATURE" },
    ],
  },
  render: LogoCloudRender,
};

export const meta = defineMeta({
  title: 'Logo Cloud',
  description: 'Logo cloud row/grid of partner or customer logos in mono or color style with optional heading; use for social-proof or partner sections.',
  categories: ["trust"],
  published: true,
});

.p1-logo-cloud__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-default);
}

.p1-logo-cloud__heading {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.14em;
  margin-block-end: var(--p1-space-lg);
  text-align: center;
  text-transform: uppercase;
}

.p1-logo-cloud__list {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--p1-space-lg) 3rem;
  justify-content: center;
}

.p1-logo-cloud__img {
  inline-size: auto;
  max-inline-size: 11.25rem;
  object-fit: contain;
}

/* Logo heights */
.p1-logo-cloud[data-height="small"] .p1-logo-cloud__img { block-size: 1.625rem; }
.p1-logo-cloud[data-height="medium"] .p1-logo-cloud__img { block-size: 2.375rem; }
.p1-logo-cloud[data-height="large"] .p1-logo-cloud__img { block-size: 3.25rem; }

/* Mono style */
.p1-logo-cloud[data-style="mono"] .p1-logo-cloud__img {
  filter: grayscale(1);
  opacity: 0.6;
}

.p1-logo-cloud__placeholder {
  color: var(--p1-border-strong);
  font-size: var(--p1-text-xl);
  font-weight: 800;
  letter-spacing: 0.05em;
}

